-- Shared, dated teacher notes for each lesson.
alter table public.lesson_records
  add column if not exists lesson_notes jsonb not null default '[]'::jsonb;

do $$ begin
  if not exists (select 1 from pg_constraint where conname='lesson_records_lesson_notes_is_array') then
    alter table public.lesson_records add constraint lesson_records_lesson_notes_is_array check (jsonb_typeof(lesson_notes)='array');
  end if;
end $$;

update public.lesson_records set lesson_notes='[{"date":"2026-08-12","body":"Day 1, Week 1, minimum day. Keep students in Homeroom until handbooks and schedules are handed out, morning announcements are reviewed, and students can sign up for lunch. Presented the syllabus. Students wrote their names for the seating chart. After the syllabus, classes had about 5–7 minutes to chat. Post the syllabus with form in ParentSquare."}]'::jsonb where lesson_code='0.1.1' and lesson_notes='[]'::jsonb;
update public.lesson_records set lesson_notes='[{"date":"2026-08-13","body":"Days 2–3, Week 1, minimum days. Thursday: ABC, lunch, rotations. Friday: DEF, lunch, rotations. Post the Safety Contract with form in ParentSquare. Add a slideshow reminder to get the syllabus and lab safety signed. Seating chart still needs work during Week 2."}]'::jsonb where lesson_code='0.1.2' and lesson_notes='[]'::jsonb;
update public.lesson_records set lesson_notes='[{"date":"2026-08-17","body":"Days 4–5, Week 2. Set up lab notebooks. Started So, I Had This Crazy Dream in A period and will give more time Tuesday. Lab safety was removed from the notebook because it duplicates the Safety Contract. Check ParentSquare signatures and give hard copies to students who still need them before Friday’s lab."}]'::jsonb where lesson_code='0.1.3' and lesson_notes='[]'::jsonb;
update public.lesson_records set lesson_notes='[{"date":"2026-08-19","body":"Handed out five lab-notebook pages: Lab Tools and Instruments Parts 1–2, The Metric System, Triple Beam Balance, and Graduated Cylinder. Students glued in the pages and completed Lab Tools and the metric system. Thursday used balances, completed the balance and graduated-cylinder pages, and posted both worksheets to Classroom. Set up Lab 1 for Friday. Create a formal presentation for this lesson."}]'::jsonb where lesson_code='0.1.4A' and lesson_notes='[]'::jsonb;
update public.lesson_records set lesson_notes='[{"date":"2026-08-21","body":"Day 8, Week 2. Give instructions for every station. Students work in groups, so encourage them to spread out and collect data efficiently."}]'::jsonb where lesson_code='0.1.5A' and lesson_notes='[]'::jsonb;
update public.lesson_records set lesson_notes='[{"date":"2026-08-24","body":"Day 9, Week 3. Used SCI101 Metric Units as the warm-up and discussed how warm-ups are graded. Started the Scientific Method lesson and completed the vocabulary with most classes."}]'::jsonb where lesson_code='0.1.4B' and lesson_notes='[]'::jsonb;
update public.lesson_records set lesson_notes='[{"date":"2026-08-25","body":"Day 10, Week 3. Used Writing a Procedure as the timed warm-up. Completed the remaining scientific-method vocabulary through variables, data, observations and inferences, and facts versus opinions."}]'::jsonb where lesson_code='0.1.5B' and lesson_notes='[]'::jsonb;
update public.lesson_records set lesson_notes='[{"date":"2026-08-26","body":"Day 11, Week 3. Gave the SCI101 Scientific Review warm-up and rewarded the first five students who scored 23/23. Gave Redi’s Experiment on Spontaneous Generation."}]'::jsonb where lesson_code='0.1.6' and lesson_notes='[]'::jsonb;
update public.lesson_records set lesson_notes='[{"date":"2026-08-27","body":"Day 12, Week 3. Lab 2: Mentos and Soda. Reviewed the write-up, showed the research video, and emphasized physical versus chemical reactions and that texture causes the reaction. Focus the question on what happens to the soda after the explosion. Demonstrated materials, went outside with goggles, then returned to finish the write-up."}]'::jsonb where lesson_code='0.1.7' and lesson_notes='[]'::jsonb;
update public.lesson_records set lesson_notes='[{"date":"2026-08-28","body":"Day 13, Week 3. Science 101 Test. Several students could not finish; allow less study time before the test so students have at least 25 minutes. Sixth grade is significantly behind seventh grade; consider making the test open-note for sixth grade."}]'::jsonb where lesson_code='0.1.0' and lesson_notes='[]'::jsonb;
update public.lesson_records set lesson_notes='[{"date":"2026-08-31","body":"Day 14, Week 4. Started Geology of Mars. Everyone received vocabulary pages. First period received the Planet Comparison Chart, but other classes did not. Create an introductory unit lesson, start vocabulary, and stop at the Planet Comparison."},{"date":"2026-09-02","body":"Day 16, Week 4. Comparing planets. Students received the Comparing Rocky Planets lab-notebook handout. Each student chooses a sphere, starts with Earth, compares other planets to Earth for about 15 minutes, shares for about 10 minutes, then receives SCI7 1.1 Comparing Rocky Planets."}]'::jsonb where lesson_code='1.1.1' and lesson_notes='[]'::jsonb;

notify pgrst, 'reload schema';
